import{_ as t,a as o,b as a,c as i,d as n,e as r}from"./chunks/da0cfa1fe3616fd5808e.Dg-lst_w.js";import{_ as s,o as l,c as h,a5 as p}from"./chunks/framework.DNkHA0lr.js";const v=JSON.parse('{"title":"The One-Person Business Revisited (Turn Yourself Into A Business)","description":"","frontmatter":{"title":"The One-Person Business Revisited (Turn Yourself Into A Business)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-one-person-business-revisited-turn-yourself-into-a-business.md","filePath":"en/letters/the-one-person-business-revisited-turn-yourself-into-a-business.md"}'),u={name:"en/letters/the-one-person-business-revisited-turn-yourself-into-a-business.md"};function c(d,e,m,y,f,g){return l(),h("div",null,[...e[0]||(e[0]=[p('<h1 id="the-one-person-business-revisited-turn-yourself-into-a-business" tabindex="-1">The One-Person Business Revisited (Turn Yourself Into A Business) <a class="header-anchor" href="#the-one-person-business-revisited-turn-yourself-into-a-business" aria-label="Permalink to &quot;The One-Person Business Revisited (Turn Yourself Into A Business)&quot;">​</a></h1><p>Dan Koe · 2023-06-16 · <a href="https://thedankoe.com/letters/the-one-person-business-revisited-turn-yourself-into-a-business/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/QoBCtcWO02g?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+t+'" alt=""></p><p>A new society has emerged.</p><p>A virtual one.</p><p>We all thought that a “virtual reality” was a few years out from existence and that it would be composed of technology like Apple’s new VR headset.</p><p>But that’s not how evolution works.</p><p>Evolution is about solving problems that cause our suffering.</p><p>It is a slow burn.</p><p>The emergence of this new society was fast like an exploding star. We called it social media.</p><p>There were burning problems in human life that led to programmers, visionaries, and businessmen building a mass solution.</p><p>Communication was local.</p><p>Information was local.</p><p>Business was local.</p><p>Opportunities were local.</p><p>Centuries of geographic restriction changed in the blink of an eye.</p><p>The internet allowed for the emergence of social media.</p><p>Social media allowed for the emergence of the creator economy.</p><p>The creator economy allowed for the advancement of decentralization.</p><p>The Industrial Revolution caused an unsustainable development of dominator hierarchies – more power and less people at the top, less power with more people at the bottom.</p><p>The Age of Information began to reverse this effect with the development of creator actualization hierarchies.</p><p>Creators educate, entertain, and inspire those beneath them with content and courses – but there is nothing holding any individual back from advancing to the top of the ladder.</p><p>Let’s deconstruct this a bit:</p><h3 id="what-is-the-creator-society" tabindex="-1">What Is The Creator Society? <a class="header-anchor" href="#what-is-the-creator-society" aria-label="Permalink to &quot;What Is The Creator Society?&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>With the development of the internet, information has spread beyond measure.</p><p>This led to the development of a more advanced, global, and accessible society.</p><p>Societies consist of institutions, and communities with shared beliefs, and cultural ideas.</p><p>The most notable aspects are the school system, workforce, social and business tribes, and religious establishments.</p><p>Social media has expanded and collapsed the lines between these.</p><p>Everything is becoming more holistic and interconnected like rain to the ocean as the pattern of Universal division and unity hints at.</p><p>The public school system had many problems:</p><ul><li>Convergent thinking</li><li>Compartmentalized learning</li><li>Conformity over authenticity</li><li>Memorization over process</li><li>Failure as something to avoid</li><li>Authorities as unquestionable</li><li>Long work over efficiency and true value</li><li>Intelligence defined by book smarts</li><li>Decade-old curriculums that only worry about training you into a replaceable job</li></ul><p>The new school system in the creator society allows individuals to:</p><ul><li>Pursue their curiosity</li><li>Find teachers (creators) that they learn best from</li><li>Treat learning as a part of life rather than an annoying obligation</li><li>Learn modern skills that allow you to adapt fast to the fast-changing environment</li><li>Find specific knowledge that contributes to their pursuit of self-generated (rather than assigned) goals</li><li>Prioritize entrepreneurship as it is the only logical end goal for those that want more out of life</li></ul><p>The new school system is internet content. None of this is labeled. It is just a part of virtual life.</p><p>The religious establishments narrowed the minds of its followers and fought any perspective that contradicted their own.</p><p>Now, spiritual awareness and education are accessible in most creator brands.</p><p>You can open your mind, study different perspectives, and self-experiment until you cultivate a philosophy that suits you.</p><p>This is not only for spiritual growth, but mental, financial, and health-related.</p><h3 id="what-is-the-creator-economy" tabindex="-1">What Is The Creator Economy? <a class="header-anchor" href="#what-is-the-creator-economy" aria-label="Permalink to &quot;What Is The Creator Economy?&quot;">​</a></h3><p>The exchange of goods has been a natural part of society since the inception of human interaction.</p><p>Value creation and exchange are the foundation of communication and relationships. Humans are deeply social creatures.</p><p>Money, or currency, is a neutral form of value.</p><p>Individuals spend it on what they perceive as valuable.</p><p>What they perceive as valuable is dependent on their identity, perspective, goals, current state of mind, and level of awareness of their problems.</p><p>We can start to see the importance of marketing and sales – as they are the main skills for illustrating the value you have to offer.</p><p>Marketing and sales take everything above into account.</p><p>If you don’t position a product or service to a specific person (identity) with a specific goal that implies a specific problem, you won’t make money.</p><p>The Creator Economy is composed of individuals distributing value in the form of content and products.</p><p>They educate their audience on the skills and interests that will aid in the actualization of their goals.</p><p>Their products or services are meant to generate results and move them faster toward those goals.</p><h2 id="my-one-person-business-philosophy" tabindex="-1">My One-Person Business Philosophy <a class="header-anchor" href="#my-one-person-business-philosophy" aria-label="Permalink to &quot;My One-Person Business Philosophy&quot;">​</a></h2><blockquote><p>There are almost 7B people on this planet. Someday, I hope, there will be almost 7B companies. – Naval</p></blockquote><p>The best businesses change lives.</p><p>And transformations make a winning product.</p><p>Stop trying to solve imaginary problems.</p><p>Solve your problems.</p><p>Change your own life.</p><p>Package up the method.</p><p>Slap a price tag on it.</p><p>You’re less likely to fail if you solve real, meaningful problems.</p><p>This is the problem with most people entering business.</p><p>They don’t have an understanding of marketing, sales, psychology, or evolution in general.</p><p>Stop trying to land on Saturn or build a billion-dollar tech company when a majority of the population is suffering from low-consciousness problems (that are holding the collective ego back from enlightenment).</p><p>Start as a <a href="/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge">micro education business</a> that helps people solve the <em>real</em> problems in their life.</p><p><em>That</em> is how you contribute to the happiness and evolution of humanity.</p><p>You do this by understanding the eternal markets: health, wealth, relationships, and happiness.</p><p>By solving your own problems in these domains, you:</p><ul><li>Push toward your own self-actualization</li><li>Create a unique map with your own story that you can pass down</li><li>Make an income by helping others heal and achieve their goals</li></ul><p>From there, everyone is at a higher state of consciousness.</p><p>We can then do what we love with our time and solve deeper problems that we are passionate about (like landing on Saturn).</p><h2 id="the-path-to-self-monetization" tabindex="-1">The Path To Self-Monetization <a class="header-anchor" href="#the-path-to-self-monetization" aria-label="Permalink to &quot;The Path To Self-Monetization&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>Social media is a new society.</p><p>Personal brands are the “people” of that society.</p><p>And no, this is not limited to people that have a business.</p><p>Creators large and small are hiring left and right.</p><p>Brands and corporations are hiring those that display their value in public.</p><p>Social media is a public job board, public school, public note-taking system, and public party where you can find friends and nurture business relationships.</p><p>To start, you can work for another creator to gain experience in the new society. This is a great option, but you can also go straight into building your own thing.</p><h3 id="path-1-learn-a-skill-sell-a-skill" tabindex="-1">Path 1) Learn A Skill, Sell A Skill <a class="header-anchor" href="#path-1-learn-a-skill-sell-a-skill" aria-label="Permalink to &quot;Path 1) Learn A Skill, Sell A Skill&quot;">​</a></h3><p>This is what most people recommend you do to start making money fast:</p><ul><li>Learn a modern skill that creators or brands use in their business (like email marketing, funnel design, or content writing)</li><li>Create content based around that skill to flex your knowledge (frankly, this won’t gain many followers. Your profile will be more like a resume).</li><li>Charge higher prices for a freelance or consulting service because you don’t have the audience to sell a product in your sleep.</li></ul><p>For any of this to work, you will have to <a href="/letters/the-1-million-dollar-skill-stack-learn-in-this-order">learn the evergreen skills</a>: writing, speaking, marketing, and sales.</p><h3 id="path-2-become-a-value-creator-around-your-interests" tabindex="-1">Path 2) Become A Value Creator Around Your Interests <a class="header-anchor" href="#path-2-become-a-value-creator-around-your-interests" aria-label="Permalink to &quot;Path 2) Become A Value Creator Around Your Interests&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>This is difficult to articulate, because the most common problem is, “I don’t have any interests.”</p><p>So let’s start there.</p><p>You create interest in a topic by investing energy in a goal.</p><p>That way you feel as if you are wasting your investment if you don’t achieve it. The pressure holds you accountable.</p><p>True goals are based on the eternal markets in pursuit of self-actualization.</p><p>The interests you learn along the way are applied to the achievement of that goal.</p><p>For the health market, I can become interested in sub-topics of nutrition, training, and mental health:</p><ul><li>Bodybuilding</li><li>The ancestral diet</li><li>Minimalist training</li><li>Yoga</li><li>Mindfulness</li></ul><p>For the wealth market, I can become interested in sub-topics of business, career development, and finance:</p><ul><li>Freelancing</li><li>Software as a service</li><li>Resume building</li><li>Interview preparation</li><li>Budgeting</li><li>Any skill listed in the previous section</li></ul><p>For the relationships market, I can become interested in sub-topics of social dynamics, dating, and marriage:</p><ul><li>Couples therapy</li><li>Confidence and charisma</li><li>Day game</li><li>How to approach</li></ul><p>All help me push toward the development of each area. This is how you become a modern Renaissance man.</p><p>You must become a lifelong autodidact (self-learner) if you want to be truly irreplaceable.</p><p>You can learn anything in record time thanks to internet content, courses, and unconventional schooling in the new society.</p><h3 id="path-3-do-both-for-maximum-effect" tabindex="-1">Path 3) Do Both For Maximum Effect <a class="header-anchor" href="#path-3-do-both-for-maximum-effect" aria-label="Permalink to &quot;Path 3) Do Both For Maximum Effect&quot;">​</a></h3><p>With a personal brand, you will be forced to learn most modern skills to make it a success.</p><p>You will have to build your own landing pages, funnels, emails, content, profile design, graphics, and the rest to make your brand a success.</p><p>If it doesn’t help your brand grow, it won’t help others, and it isn’t worth learning in this case.</p><p>When you get results for your own brand, you then have the knowledge to help others with theirs.</p><p>The product or service you will sell (to practice your skill development) will be based on your interests.</p><p>You will create a minimum viable offer around those interests with a freelance or consulting service.</p><p>As you grow your audience with the content you produce, you can eventually turn that into a product that sells with less effort.</p><p>This is a longer path, but oh so worth it.</p><p>You drastically improve yourself, and your business has more leverage than most out there.</p><h2 id="the-4-pillars-of-a-6-figure-one-person-business" tabindex="-1">The 4 Pillars Of A 6-Figure One-Person Business <a class="header-anchor" href="#the-4-pillars-of-a-6-figure-one-person-business" aria-label="Permalink to &quot;The 4 Pillars Of A 6-Figure One-Person Business&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>The one-person business model can have many definitions.</p><p>And now that I have a small team, I can’t really call myself a “one-person business,” but I’m going to redefine it so that I can (lol).</p><p>On top of that, I pushed a bit too far into a business model I don’t care for. I am actively working to get back to one person and maybe a VA. I’m okay with the decrease in income that comes from that.</p><p>I’ve realized what I want (writing and creative challenges) which allows me to ruthlessly eliminate what stands in the way (with time).</p><p>The one-person business model is <em>turning yourself into the business.</em></p><p>It is a novel and attention-grabbing way of saying, “<em>Become high-value and put yourself out there until enough people know who you are, what you do, and why you do it. Opportunities will compound.”</em></p><p>In a nutshell, that’s all you really need to do to succeed.</p><p>For clarity, let’s dive into the 4 pillars of the one-person business:</p><p><img src="'+r+'" alt=""></p><h3 id="brand-–-you-are-the-niche" tabindex="-1">Brand – You Are The Niche <a class="header-anchor" href="#brand-–-you-are-the-niche" aria-label="Permalink to &quot;Brand – You Are The Niche&quot;">​</a></h3><p>Your personal brand is your “self” or “identity” in the new society.</p><p>Your identity is the underlying story that shapes your perspective.</p><p>Your perspective contains goals from which you perceive situations.</p><p>These goals can be assigned to you (social conditioning) or self-generated (in alignment with your vision).</p><p>When you read a book, you will interpret it differently from the next person, because you have different goals as your lens.</p><p>If I read the book <em>Awareness</em> at a low financial point in my life, I will absorb ideas related to reaching my financial vision (that I can distribute in my content).</p><p>Another person that reads the book at a high relationship point in their life, they may get nothing from it, or absorb ideas to aid in the nurturing of that relationship.</p><p>Your brand is your vision for the future (and you vision evolves as you do).</p><p>Your vision for the future implies that you have, or are learning, the skills and interests necessary to achieve it.</p><p>Your job is to illustrate this wherever a reader can come in contact with you. All of your content will be written from the lens of your brand.</p><p>If my current vision / goal / purpose is to make more money…</p><p>And the skills I’ve learned or am learning are marketing, health, and spirituality…</p><p>My bio would be, “I write about marketing, health, and spirituality so you can build a holistic one-person business.”</p><p>Yes, even health and spirituality can be framed as a way to help with business. This is where most people get confused about incorporating their interests into a confined niche they feel tied to.</p><p>What are you leading people toward?</p><p>That’s how you attract followers.</p><h3 id="content-–-documenting-your-mind" tabindex="-1">Content – Documenting Your Mind <a class="header-anchor" href="#content-–-documenting-your-mind" aria-label="Permalink to &quot;Content – Documenting Your Mind&quot;">​</a></h3><p>I like to think of social media as a public note-taking system where you jot down:</p><ul><li>What you are learning and how it applies to your life</li><li>Your thoughts and opinions on your skills and interests</li><li>The lessons you are learning throughout the story of life</li></ul><p>Without knowing it, we are actively building out the collective consciousness in an explorable fashion on the internet.</p><p>But, you can’t just write things out and pray that you grow your brand.</p><p>You have to study marketing, and persuasion, and immerse yourself in content that does well so you can note the patterns between them all.</p><p>I would recommend the free course on the <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> landing page – you just enter your email at the top of the page.</p><p>If you haven’t learned marketing, sales, or copywriting – start now. They will change your life. And there is too much to go over in this letter about them (double and I’ve talked about them multiple times before, <a href="/letters/value-creation-the-skill-that-built-my-one-person-business">this letter is a good starting point</a>).</p><h3 id="product-–-public-personal-projects" tabindex="-1">Product – Public Personal Projects <a class="header-anchor" href="#product-–-public-personal-projects" aria-label="Permalink to &quot;Product – Public Personal Projects&quot;">​</a></h3><p>Under the one-person business philosophy, you contribute to the new society by solving your own problems and selling the solution.</p><p>Here’s the progression:</p><ul><li>Identify a problem in your life</li><li>Turn it into a personal project for experience</li><li>Turn it into a minimum viable offer</li><li>Start selling for $500-$1000 (freelancing or consulting)</li><li>Build your audience along the way with content</li><li>Increase the depth and complexity of your offer</li><li>Productize it when you feel ready so it can sell in your sleep</li></ul><p>This will take 1-3 years.</p><p>If your goal is to make more money in business or your career, you can learn a skill like email marketing.</p><p>If your goal is to get ripped and increase your attraction &amp; confidence, you can go to the gym and fix your nutrition.</p><p>Once you do, you can begin selling it as a freelance or consulting service.</p><p>With the email marketing example, freelance is the obvious option.</p><p><em>Teaching</em> others often gets swept under the rug.</p><p>You can teach other creators or brands what you’ve learned in your email marketing pursuits – especially <em>if you applied it to your own brand and saw results along the way</em>_._</p><p>Where does a “project” come into play?</p><p>Projects are how you actually solve your problems in the real world.</p><p>They force you to apply what you learn.</p><p>They are also tangible, they are your result.</p><p>You can iterate on them and get better with time.</p><p>You can reflect on them and make it easier to achieve for the next person.</p><p>With email marketing, write an email sequence for your own brand. You can practice selling someone else’s product (affiliate), or practice promoting your favorite books or products. Craft a persuasive argument around them.</p><p>Then, do the same thing for your favorite brand. Build them an email sequence.</p><p>Now that you have real-world practice, you can either pitch your services to that brand, or start helping others build their own out.</p><p>Teaching is how you identify knowledge gaps.</p><p>That is the only way you will be able to fill them.</p><p>By not building projects and teaching what you learn, your journey will be slow and painful.</p><h3 id="marketing-–-sell-to-yourself" tabindex="-1">Marketing – Sell To Yourself <a class="header-anchor" href="#marketing-–-sell-to-yourself" aria-label="Permalink to &quot;Marketing – Sell To Yourself&quot;">​</a></h3><p>You won’t make a single penny if you never promote yourself.</p><p>Simple as that.</p><p>People ask me (from a state of stress, overwhelm, and panic) why they aren’t making money from their efforts.</p><p>It’s because they do everything but promote their products or services.</p><p>Marketing exists across the entirety of your brand but is most prevalent in:</p><ul><li>Your landing pages for your products and services</li><li>Your emails where you promote them</li><li>Your content where you promote them</li><li>Your outreach messages where you see if others are a fit for them</li></ul><p>Again, I’ve talked about this all before, and I give my exact systems in <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>, so let’s go over a framework you can practice with.</p><p><strong>Identify Their Goals or Desired Outcome</strong></p><p>You have to know what your audience wants.</p><p>Make it top-of-mind by asking them or illustrating what the goal is in your marketing.</p><p>When you are the niche, this is a goal that you’ve already achieved. You should already know what is desirable to your audience through self-reflection.</p><p><strong>Identify What Is Standing In The Way</strong></p><p>What is the reason people aren’t achieving their goals?</p><p>What is the reason you didn’t achieve the goal at the start?</p><p>Write it out in your promotions or ask the person you are talking to in your outreach messages.</p><p>“What’s preventing you from achieving [the goal they mentioned]?”</p><h3 id="present-your-solution-to-solve-a-burning-problem" tabindex="-1">Present Your Solution To Solve A Burning Problem <a class="header-anchor" href="#present-your-solution-to-solve-a-burning-problem" aria-label="Permalink to &quot;Present Your Solution To Solve A Burning Problem&quot;">​</a></h3><p>Now that they are clear on the goal and what is standing in the way, you know whether or not they are a fit for your solution.</p><p>If they aren’t, wish them a good day and leave them alone.</p><p>If they are, ask them how their life would be impacted if they could achieve that goal – this shines a light on the problem they are facing.</p><p>From here, you can present your offer as a potential solution.</p><p>To practice this process more as a beginner, read this letter on <a href="/letters/how-to-network-with-millionaires-and-build-a-name-for-yourself">The Non-Needy Networking Process</a>.</p><p>That’s all you need to know about the one-person business model for now.</p><p>Feel free to watch through the rest of <a href="https://youtube.com/playlist?list=PLB4ePXk6nBaeG3fD13NaRMsRsEc2iCsV4" target="_blank" rel="noreferrer">The One Person Business playlist</a> on my YouTube.</p><p>Enjoy the rest of your day.</p><p>– Dan Koe</p>',199)])])}const k=s(u,[["render",c]]);export{v as __pageData,k as default};
